import { useMemo } from "react";
import katex from "katex";

import "katex/dist/katex.min.css";

import { cn } from "@/lib/utils";

/**
 * A single LaTeX expression typeset with KaTeX.
 *
 * KaTeX turns the LaTeX into markup locally with `trust: false`, so the only
 * HTML injected here is generated by KaTeX itself — model-provided HTML, tags
 * or event attributes can never reach the DOM. When an expression cannot be
 * parsed it is shown as raw code instead of throwing, so a single malformed
 * equation can never break the surrounding page.
 */
export function MathExpression({
  latex,
  display = false,
  className,
}: {
  latex: string;
  display?: boolean;
  className?: string;
}) {
  const html = useMemo(() => {
    const source = latex.trim();
    if (!source) return null;
    try {
      return katex.renderToString(source, {
        displayMode: display,
        throwOnError: false,
        strict: false,
        trust: false,
        output: "htmlAndMathml",
      });
    } catch {
      return null;
    }
  }, [latex, display]);

  if (html === null) {
    return (
      <code className={cn("rounded bg-muted px-1 py-0.5 font-mono text-[0.85em]", className)}>
        {latex}
      </code>
    );
  }

  return (
    <span
      className={cn(
        "lumio-math",
        display && "lumio-math-display block max-w-full overflow-x-auto overflow-y-hidden",
        className,
      )}
      // Markup generated locally by KaTeX from LaTeX — never from model HTML.
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}
